add_filter( 'woocommerce_product_upsells_products_heading', 'perfectpixel_upsells_heading' );
add_filter( 'woocommerce_product_loop_start', 'perfectpixel_upsells_subheading' );

function perfectpixel_upsells_heading( $heading ) {
	$custom = trim( '{{upsells_heading}}' );
	return '' !== $custom ? $custom : $heading;
}

function perfectpixel_upsells_subheading( $html ) {
	$text = trim( '{{upsells_subheading}}' );
	if ( '' !== $text && 'up-sells' === wc_get_loop_prop( 'name' ) ) {
		$html = '<p class="perfectpixel-upsells-subheading">' . esc_html( $text ) . '</p>' . $html;
	}
	return $html;
}
